import hashlib, heapq, random, time

class TopKSketchPane:
    def __init__(self, k: int = 10, d: int = 4, w: int = 2048):
        self.k, self.d, self.w = k, d, w
        self.table = [[0] * w for _ in range(d)]
        self.topk_map: dict[str, int] = {}

def _hashes(self, key: str) -> list[int]:
        digest = hashlib.blake2b(key.encode(), digest_size=16).digest()
        h1 = int.from_bytes(digest[:8], 'big')
        h2 = int.from_bytes(digest[8:], 'big') | 1
        return [((h1 + i * h2) & 0xFFFFFFFFFFFFFFFF) % self.w for i in range(self.d)]

def add(self, key: str, count: int = 1) -> int:
        est = None
        for r, col in enumerate(self._hashes(key)):
            self.table[r][col] += count
            val = self.table[r][col]
            est = val if est is None or val < est else est
        assert est is not None
        if key in self.topk_map or len(self.topk_map) < self.k:
            self.topk_map[key] = est
        else:
            min_k, min_v = min(self.topk_map.items(), key=lambda kv: kv[1])
            if est > min_v:
                del self.topk_map[min_k]
                self.topk_map[key] = est
        return est

