def flush_pane_with_retry(sink_fn, payload: bytes, max_retries: int = 3) -> None:
    for attempt in range(max_retries):
        try:
            sink_fn(payload)
            return
        except OSError as exc:
            if attempt == max_retries - 1:
                raise RuntimeError(f'Pane flush failed: {exc}') from exc
            time.sleep((0.2 * (2 ** attempt)) + random.uniform(0, 0.1))
